window.TEXTOS_SEED["sabedoria"][1] = [
{s:"Amai a justiça"},
{v:1,l:["Amai a justiça, vós que governais a terra;","pensai no Senhor com retidão","e procurai-o com simplicidade de coração,"],n:"O livro foi escrito em grego, provavelmente em Alexandria, no último século antes de Cristo. O autor fala em nome de Salomão (capítulos 7–9), mas não o nomeia."},
{v:2,l:["pois ele se deixa encontrar pelos que não o põem à prova","e se manifesta aos que não lhe negam a confiança."],np:1},
{v:3,l:["Os pensamentos tortuosos afastam de Deus,","e o seu poder, posto à prova, confunde os insensatos."],np:1},
{v:4,l:["A sabedoria não entra numa alma que trama o mal,","nem habita num corpo escravo do pecado."],np:1},
{v:5,l:["Pois o espírito santo, que educa, foge da falsidade,","afasta-se dos pensamentos insensatos","e se retira quando sobrevém a injustiça."],np:1},
{v:6,l:["A sabedoria é um espírito que ama os homens,","mas não deixa impune o blasfemo pelas suas palavras,","pois Deus é testemunha dos seus rins,","observador verdadeiro do seu coração","e ouvinte da sua língua."],np:1},
{v:7,l:["Pois o espírito do Senhor enche o universo,","e ele, que mantém unidas todas as coisas, conhece toda palavra."],np:1},
{v:8,l:["Por isso, quem diz coisas injustas não passará despercebido,","e a justiça, que condena, não o deixará escapar."],np:1},
{v:9,l:["Os desígnios do ímpio serão examinados,","e o eco das suas palavras chegará até o Senhor,","para condenação das suas iniquidades."],np:1},
{v:10,l:["Pois um ouvido zeloso tudo ouve,","e nem o sussurro das murmurações lhe fica oculto."],np:1},
{v:11,l:["Guardai-vos, pois, da murmuração inútil","e poupai a língua da maledicência,","pois nem a palavra dita em segredo fica sem efeito,","e a boca mentirosa mata a alma."],np:1},
{s:"Deus não fez a morte"},
{v:12,l:["Não procureis a morte com os desvios da vossa vida,","nem atraiais a ruína com as obras das vossas mãos,"]},
{v:13,l:["pois Deus não fez a morte,","nem se alegra com a perdição dos vivos."],np:1},
{v:14,l:["Ele criou todas as coisas para que existissem,","e as criaturas do mundo são salutares;","nelas não há veneno de morte,","nem a morada dos mortos reina sobre a terra."],np:1},
{v:15,l:["Pois a justiça é imortal."],np:1},
{v:16,l:["Mas os ímpios chamam a morte com gestos e palavras;","tendo-a por amiga, consomem-se por ela","e fazem aliança com ela,","pois merecem pertencer-lhe."],np:1}
];

window.TEXTOS_SEED["sabedoria"][2] = [
{s:"O raciocínio dos ímpios"},
{v:1,l:["Pois dizem entre si, raciocinando mal:","Breve e triste é a nossa vida,","não há remédio quando chega o fim do homem,","e não se conhece ninguém que tenha voltado da morada dos mortos."]},
{v:2,l:["Nascemos por acaso,","e depois seremos como se nunca tivéssemos existido;","o sopro das nossas narinas é fumaça,","e o pensamento, uma centelha no bater do nosso coração;"],np:1},
{v:3,l:["quando ela se apaga, o corpo se reduz a cinza,","e o espírito se dissipa como ar leve."],np:1},
{v:4,l:["Com o tempo o nosso nome será esquecido,","e ninguém se lembrará das nossas obras;","a nossa vida passará como o rastro de uma nuvem,","e se dissipará como a névoa","expulsa pelos raios do sol","e desfeita pelo seu calor."],np:1},
{v:5,l:["O nosso tempo é a passagem de uma sombra,","e o nosso fim não tem volta,","pois está selado, e ninguém retorna."],np:1},
{v:6,l:["Vinde, pois, gozemos dos bens presentes,","aproveitemos as criaturas com o ardor da juventude."],np:1},
{v:7,l:["Fartemo-nos de vinho precioso e de perfumes,","e não deixemos passar a flor da primavera;"],np:1},
{v:8,l:["coroemo-nos de botões de rosa antes que murchem."],np:1},
{v:9,l:["Que nenhum de nós fique sem parte na nossa orgia;","deixemos por toda parte sinais da nossa alegria,","pois esta é a nossa parte, esta é a nossa sorte."],np:1,n:"Nenhum de nós: assim o grego; a Nova Vulgata diz: nenhum prado."},
{v:10,l:["Oprimamos o justo que é pobre,","não poupemos a viúva,","nem respeitemos os cabelos brancos do ancião."],np:1},
{v:11,l:["Que a nossa força seja a norma da justiça,","pois o que é fraco se mostra inútil."],np:1},
{v:12,l:["Armemos ciladas ao justo, porque nos incomoda,","opõe-se às nossas obras,","censura-nos as faltas contra a lei","e nos acusa de faltas contra a educação que recebemos."],np:1},
{v:13,l:["Pretende ter o conhecimento de Deus","e se chama filho do Senhor."],np:1,n:"Filho do Senhor: em grego pais, que significa também servo (compare Isaías 52,13–53,12)."},
{v:14,l:["Tornou-se para nós uma censura dos nossos pensamentos;","só de vê-lo nos é insuportável,"],np:1},
{v:15,l:["pois a sua vida é diferente da dos outros,","e os seus caminhos são estranhos."],np:1},
{v:16,l:["Ele nos considera moeda falsa","e se afasta dos nossos caminhos como de imundícies;","proclama feliz o fim dos justos","e se gaba de ter Deus por pai."],np:1},
{v:17,l:["Vejamos se as suas palavras são verdadeiras","e experimentemos o que acontecerá no seu fim."],np:1},
{v:18,l:["Pois, se o justo é filho de Deus, Deus o socorrerá","e o livrará das mãos dos seus adversários."],np:1,n:"Compare Mateus 27,43."},
{v:19,l:["Provemo-lo com ultrajes e torturas,","para conhecermos a sua mansidão","e pormos à prova a sua paciência."],np:1},
{v:20,l:["Condenemo-lo a uma morte infame,","pois, segundo as suas palavras, Deus o visitará."],np:1},
{s:"O erro dos ímpios"},
{v:21,l:["Assim pensam, mas se enganam:","a sua maldade os cegou."]},
{v:22,l:["Não conhecem os segredos de Deus,","não esperam a recompensa da santidade,","nem acreditam no prêmio das almas irrepreensíveis."],np:1},
{v:23,l:["Pois Deus criou o homem para a incorruptibilidade","e o fez imagem da sua própria eternidade."],np:1,n:"Da sua própria eternidade: assim o grego; a Nova Vulgata diz: imagem da sua semelhança."},
{v:24,l:["Mas pela inveja do diabo a morte entrou no mundo,","e a experimentam os que pertencem ao seu partido."],np:1}
];

